			assert(center.is_equal_approx(Vector3(spec.fixture_center[0],spec.fixture_center[1],spec.fixture_center[2])))
	var aft:Node3D=ship.get_node("ShipSpace/Districts/AftPublicCore_WIP/PrimaryCoreEnclosure")
